def create_protocols(apps, schema_editor):
    """Projects that exist before this migration get the default protocol (season 1 Apr - 30 Sep)."""
    Project = apps.get_model("projects", "Project")
    ProjectProtocol = apps.get_model("projects", "ProjectProtocol")
    for project in Project.objects.filter(protocol__isnull=True):
        year = project.start_date.year
        ProjectProtocol.objects.create(
            project=project,
            season_start=datetime.date(year, 4, 1),
            season_end=datetime.date(year, 9, 30),
        )


